            <span class="token string single-quoted-string">'headerOptions'</span> <span class="token operator">=></span> <span class="token punctuation">[</span> <span class="token string single-quoted-string">'class'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'col-md-2'</span> <span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">'filter'</span> <span class="token operator">=></span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\</span>kartik<span class="token punctuation">\</span>widgets<span class="token punctuation">\</span>DatePicker</span><span class="token operator">::</span><span class="token function">widget</span><span class="token punctuation">(</span>
                <span class="token punctuation">[</span>   
    
                    <span class="token string single-quoted-string">'id'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'filterDuedate'</span><span class="token punctuation">,</span>
