                    <span class="token string single-quoted-string">'attribute'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'ddrStart'</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">'value'</span> <span class="token operator">=></span> <span class="token string double-quoted-string">"1970-01-01"</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">'attribute2'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'ddrEnd'</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">'value2'</span> <span class="token operator">=></span> <span class="token string double-quoted-string">"5000-12-31"</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">'size'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'sm'</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">'separator'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">''</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">'type'</span> <span class="token operator">=></span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\</span>kartik<span class="token punctuation">\</span>widgets<span class="token punctuation">\</span>DatePicker</span><span class="token operator">::</span><span class="token constant">TYPE_RANGE</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">'convertFormat'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'true'</span><span class="token punctuation">,</span>
