<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token doc-comment comment">/**
 * Generate a simple message page with predefined colors (info, warning, error)
 *
 * <span class="token keyword">@param</span> <span class="token class-name"><span class="token keyword">string</span></span> <span class="token parameter">$type</span> info|warning|err different background colors
 * <span class="token keyword">@param</span> <span class="token class-name"><span class="token keyword">string</span></span> <span class="token parameter">$message</span> The message to display
 * <span class="token keyword">@return</span> <span class="token class-name"><span class="token keyword">string</span></span> Full HTML page definition
 */</span>
<span class="token keyword">function</span> <span class="token function-definition function">generateFlashPage</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token operator">=</span><span class="token string single-quoted-string">'info'</span><span class="token punctuation">,</span> <span class="token variable">$message</span><span class="token operator">=</span><span class="token string single-quoted-string">'Please wait...'</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$style</span><span class="token operator">=</span><span class="token string single-quoted-string">'&lt;style>'</span>
            <span class="token operator">.</span><span class="token string single-quoted-string">'.err {background-color: lightCoral;}'</span>
            <span class="token operator">.</span><span class="token string single-quoted-string">'.info {background-color: yellowGreen;}'</span>
            <span class="token operator">.</span><span class="token string single-quoted-string">'.warning {background-color: gold;}'</span>
            <span class="token operator">.</span><span class="token string single-quoted-string">'.msg {margin: 20px; text-align: center;}'</span>
            <span class="token operator">.</span><span class="token string single-quoted-string">'h1 {padding:12px; margin: 40px;}'</span>
            <span class="token operator">.</span><span class="token string single-quoted-string">'&lt;/style>'</span><span class="token punctuation">;</span>
    <span class="token variable">$htmlpre</span><span class="token operator">=</span><span class="token string single-quoted-string">'&lt;html>&lt;head>&lt;title>HiSATv2 message&lt;/title>'</span><span class="token operator">.</span><span class="token variable">$style</span><span class="token operator">.</span><span class="token string single-quoted-string">'&lt;/head>&lt;body>'</span><span class="token punctuation">;</span>
    <span class="token variable">$htmlsuf</span><span class="token operator">=</span><span class="token string single-quoted-string">'&lt;/body>&lt;/html>'</span><span class="token punctuation">;</span>
    <span class="token variable">$msgtype</span><span class="token operator">=</span><span class="token string single-quoted-string">'info'</span><span class="token punctuation">;</span>
    <span class="token variable">$msgpre</span><span class="token operator">=</span><span class="token string single-quoted-string">'&lt;div class="msg">&lt;h1 class="'</span><span class="token operator">.</span><span class="token variable">$type</span><span class="token operator">.</span><span class="token string single-quoted-string">'">'</span><span class="token punctuation">;</span>
    <span class="token variable">$msgsuf</span><span class="token operator">=</span><span class="token string single-quoted-string">'&lt;/h1>&lt;/div>'</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token variable">$htmlpre</span><span class="token operator">.</span><span class="token variable">$msgpre</span><span class="token operator">.</span><span class="token variable">$message</span><span class="token operator">.</span><span class="token variable">$msgsuf</span><span class="token operator">.</span><span class="token variable">$htmlsuf</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token variable">$message</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
<span class="token keyword">try</span> <span class="token punctuation">{</span>
    <span class="token variable">$app</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">yii<span class="token punctuation">\</span>web<span class="token punctuation">\</span>Application</span><span class="token punctuation">(</span><span class="token variable">$config</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified"><span class="token punctuation">\</span>yii<span class="token punctuation">\</span>db<span class="token punctuation">\</span>Exception</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$message</span> <span class="token operator">=</span> <span class="token constant">MAINT_MSG_DB</span><span class="token operator">.</span><span class="token string single-quoted-string">'&lt;br/>Additonal info: '</span><span class="token operator">.</span><span class="token variable">$ex</span><span class="token operator">-></span><span class="token function">getMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">try</span> <span class="token punctuation">{</span>
    <span class="token variable">$app</span><span class="token operator">-></span><span class="token property">db</span><span class="token operator">-></span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified"><span class="token punctuation">\</span>yii<span class="token punctuation">\</span>db<span class="token punctuation">\</span>Exception</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$message</span> <span class="token operator">=</span> <span class="token variable">$ex</span><span class="token operator">-></span><span class="token function">getMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">db</span><span class="token operator">-></span><span class="token function">getIsActive</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$message</span> <span class="token operator">=</span> <span class="token constant">MAINT_MSG_DB</span><span class="token operator">.</span><span class="token string single-quoted-string">'&lt;br/>Connection is not active.'</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
    <span class="token variable">$serverip</span> <span class="token operator">=</span> <span class="token variable">$_SERVER</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'SERVER_ADDR'</span><span class="token punctuation">]</span> <span class="token operator">??</span> <span class="token constant">null</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$serverip</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$rparams</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
        <span class="token variable">$query</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">yii<span class="token punctuation">\</span>db<span class="token punctuation">\</span>Query</span><span class="token punctuation">;</span>
        <span class="token keyword">try</span> <span class="token punctuation">{</span>
            <span class="token variable">$rparams</span> <span class="token operator">=</span> <span class="token variable">$query</span><span class="token operator">-></span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'ip, mtc_mode'</span><span class="token punctuation">)</span><span class="token operator">-></span><span class="token function">from</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'runtime_parameter'</span><span class="token punctuation">)</span>
                    <span class="token operator">-></span><span class="token function">where</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'ip'</span> <span class="token operator">=></span> <span class="token variable">$serverip</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
                    <span class="token operator">-></span><span class="token function">createCommand</span><span class="token punctuation">(</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">db</span><span class="token punctuation">)</span>
                    <span class="token operator">-></span><span class="token function">queryOne</span><span class="token punctuation">(</span><span class="token class-name static-context">PDO</span><span class="token operator">::</span><span class="token constant">FETCH_ASSOC</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified">yii<span class="token punctuation">\</span>db<span class="token punctuation">\</span>Exception</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$message</span> <span class="token operator">=</span> <span class="token string single-quoted-string">'Database exception: '</span><span class="token operator">.</span><span class="token variable">$ex</span><span class="token operator">-></span><span class="token function">getMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$rparams</span> <span class="token operator">&amp;&amp;</span> <span class="token variable">$rparams</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'mtc_mode'</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">strtoupper</span><span class="token punctuation">(</span><span class="token variable">$rparams</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'mtc_mode'</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">'ON'</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token variable">$message</span> <span class="token operator">=</span> <span class="token constant">MAINT_MSG_MM</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
            <span class="token variable">$message</span> <span class="token operator">=</span> <span class="token constant">MAINT_MSG_ERR</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
        <span class="token variable">$message</span> <span class="token operator">=</span> <span class="token constant">MAINT_MSG_ERR</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
<span class="token keyword">unset</span><span class="token punctuation">(</span><span class="token variable">$app</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token function">generateFlashPage</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token operator">==</span><span class="token constant">MAINT_MSG_MM</span> <span class="token operator">?</span> <span class="token string single-quoted-string">'info'</span><span class="token punctuation">:</span><span class="token string single-quoted-string">'err'</span><span class="token punctuation">,</span> <span class="token variable">$message</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">exit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
