ber"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="browser-language-detection" tabindex="-1"><a class="header-anchor" href="#browser-language-detection" aria-hidden="true">#</a> Browser language detection</h2>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token comment">// TBC</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="accessrule-for-custom-access-control" tabindex="-1"><a class="header-anchor" href="#accessrule-for-custom-access-control" aria-hidden="true">#</a> AccessRule for custom access control</h2>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">namespace</span> <span class="token package">frontend<span class="token punctuation">\</span>components</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">frontend<span class="token punctuation">\</span>models<span class="token punctuation">\</span>User</span><span class="token punctuation">;</span>
<span class="token keyword">class</span> <span class="token class-name-definition class-name">AccessRule</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\</span>yii<span class="token punctuation">\</span>filters<span class="token punctuation">\</span>AccessRule</span> <span class="token punctuation">{</span>

    <span class="token doc-comment comment">/**
     * <span class="token keyword">@inheritdoc</span>
     */</span>
    <span class="token keyword">protected</span> <span class="token keyword">function</span> <span class="token function-definition function">matchRole</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">empty</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-></span><span class="token property">roles</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-></span><span class="token property">roles</span> <span class="token keyword">as</span> <span class="token variable">$role</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$role</span> <span class="token operator">==</span> <span class="token string single-quoted-string">'?'</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token operator">-></span><span class="token function">getIsGuest</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
            <span class="token punctuation">}</span> <span class="token keyword">elseif</span> <span class="token punctuation">(</span><span class="token variable">$role</span> <span class="token operator">==</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\</span>frontend<span class="token punctuation">\</span>controllers<span class="token punctuation">\</span>UserController</span><span class="token operator">::</span><span class="token constant">ROLE_USER</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$user</span><span class="token operator">-></span><span class="token function">getIsGuest</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
            <span class="token comment">// Check if the user is logged in, and the roles match</span>
            <span class="token punctuation">}</span> <span class="token keyword">elseif</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$user</span><span class="token operator">-></span><span class="token function">getIsGuest</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> <span class="token variable">$role</span> <span class="token operator">==</span> <span class="token variable">$user</span><span class="token operator">-></span><span class="token property">identity</span><span class="token operator">-></span><span class="token property">status</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span>
     
        <span class="token keyword">return</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="using-https-inside-an-http-based-yii2-application" tabindex="-1"><a class="header-anchor" href="#using-https-inside-an-http-based-yii2-application" aria-hidden="true">#</a> Using HTTPS inside an HTTP based Yii2 application</h2>
<ul>
<li>
<p>Setup your proxy configuration (if needed) by exporting HTTP_PROXY and HTTPS_PROXY variables</p>
</li>
<li>
<p>Self-update your composer</p>
</li>
</ul>
<div class="language-bash ext-sh line-numbers-mode"><pre v-pre class="language-bash"><code>  <span class="token function">composer</span> <span class="token parameter variable">-vv</span> <span class="token parameter variable">--ansi</span> selfupdate
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul>
<li>Install the yii2tech/https Yii2 extension</li>
</ul>
<div class="language-bash ext-sh line-numbers-mode"><pre v-pre class="language-bash"><code>  <span class="token function">composer</span> <span class="token parameter variable">-v</span> <span class="token parameter variable">--ansi</span> require --prefer-dist <span class="token string">"yii2tech/https"</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="accesscontrol-denycallback-snippet" tabindex="-1"><a class="header-anchor" href="#accesscontrol-denycallback-snippet" aria-hidden="true">#</a> AccessControl denyCallback snippet</h2>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code>        <span class="token comment">// Check for VI tool access is authorized</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span> <span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">user</span><span class="token operator">-></span><span class="token class-name">isGuest</span> <span class="token operator">||</span> <span class="token class-name">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">user</span><span class="token operator">-></span><span class="token property">identity</span><span class="token operator">-></span><span class="token function">is</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'admin'</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">session</span><span class="token operator">-></span><span class="token function">setFlash</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'danger'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'You are not allowed to do this!'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token function">renderContent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'&lt;a class="btn btn-primary" href="javascript:history.back()">Back&lt;/a>'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The flash display code in layouts/main.php</p>
