                    <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">'denyCallback'</span> <span class="token operator">=></span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$rule</span><span class="token punctuation">,</span> <span class="token variable">$action</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    <span class="token class-name static-context">Access</span><span class="token operator">::</span><span class="token function">showNAPage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span><span class="token punctuation">,</span>
            <span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="raoul-s-workflow-handler-get-the-available-statuses" tabindex="-1"><a class="header-anchor" href="#raoul-s-workflow-handler-get-the-available-statuses" aria-hidden="true">#</a> Raoul's Workflow handler (get the available statuses)</h2>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'id'</span><span class="token operator">=></span><span class="token number">42</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">if</span><span class="token punctuation">(</span> <span class="token variable">$post</span><span class="token operator">-></span><span class="token function">hasWorkflowStatus</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>

    <span class="token comment">// let's ask the Status object then</span>
    <span class="token variable">$transitions</span> <span class="token operator">=</span> <span class="token variable">$post</span>
        <span class="token operator">-></span><span class="token function">getWorkflowStatus</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token operator">-></span><span class="token function">getTransitions</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">foreach</span><span class="token punctuation">(</span> <span class="token variable">$transitions</span> <span class="token keyword">as</span> <span class="token variable">$transition</span> <span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">echo</span> <span class="token variable">$transition</span><span class="token operator">-></span><span class="token function">getEndStatus</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-></span><span class="token function">getId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="user-role-management" tabindex="-1"><a class="header-anchor" href="#user-role-management" aria-hidden="true">#</a> User role management</h2>
<p>cm, vm: no update
oss : oss, plsc, cm
exportc: exportc
plsc: cm, plsc
sib: sib, vm</p>
<p>name, email: only for admin</p>
<h2 id="checkboxlist-with-separators" tabindex="-1"><a class="header-anchor" href="#checkboxlist-with-separators" aria-hidden="true">#</a> CheckboxList with separators</h2>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token variable">$form</span><span class="token operator">-></span><span class="token function">field</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'roles_set'</span><span class="token punctuation">)</span><span class="token operator">-></span><span class="token function">radioList</span><span class="token punctuation">(</span><span class="token variable">$checks</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">'class'</span><span class="token operator">=></span><span class="token string single-quoted-string">'checkboxlist'</span><span class="token punctuation">,</span> 
    <span class="token comment">// Custom radiobutton tag generator function</span>
    <span class="token string single-quoted-string">'item'</span> <span class="token operator">=></span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$index</span><span class="token punctuation">,</span> <span class="token variable">$label</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$checked</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Radiobutton labels after we need a separator</span>
        <span class="token variable">$users_wsep</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">'Normal User'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'Vulnerability Manager'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'Sen in Black'</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
        <span class="token comment">// Generate the standard radiobutton</span>
        <span class="token variable">$res</span> <span class="token operator">=</span> <span class="token string double-quoted-string">"&lt;label>&lt;input type='radio' name='User[roles_set]' value=<span class="token interpolation"><span class="token variable">$value</span></span>> <span class="token interpolation"><span class="token variable">$label</span></span>&lt;/label>"</span><span class="token punctuation">;</span>
        <span class="token comment">// Add the separator where needed</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span> <span class="token function">in_array</span><span class="token punctuation">(</span><span class="token variable">$label</span><span class="token punctuation">,</span> <span class="token variable">$users_wsep</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$res</span> <span class="token operator">.=</span> <span class="token string single-quoted-string">'&lt;hr>'</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">return</span> <span class="token variable">$res</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="gridview-without-pagination" tabindex="-1"><a class="header-anchor" href="#gridview-without-pagination" aria-hidden="true">#</a> GridView without pagination</h2>
<p><strong>for the action()</strong>:</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code>    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">actionX</span><span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">,</span> <span class="token variable">$onepage</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token operator">...</span>
        <span class="token comment">// setup dataProvider</span>
        <span class="token operator">...</span>
        <span class="token comment">// turn off pagination</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token function">is_null</span><span class="token punctuation">(</span><span class="token variable">$onepage</span><span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> <span class="token variable">$onepage</span> <span class="token operator">==</span> <span class="token string single-quoted-string">'1'</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$dataProvider</span><span class="token operator">-></span><span class="token function">setPagination</span><span class="token punctuation">(</span><span class="token constant boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>for the view</strong>:</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code>    <span class="token doc-comment comment">/*** define the layout ***/</span>
    <span class="token variable">$gridLayout</span> <span class="token operator">=</span> <span class="token string double-quoted-string">"&lt;span>"</span> <span class="token operator">.</span> <span class="token class-name static-context">Html</span><span class="token operator">::</span><span class="token function">a</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Show all'</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">'view'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'id'</span> <span class="token operator">=></span> <span class="token variable">$model</span><span class="token operator">-></span><span class="token property">id</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'onepage'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'1'</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">.</span> <span class="token string double-quoted-string">"&lt;/span>{summary}{items}{pager}"</span><span class="token punctuation">;</span>
    <span class="token keyword">echo</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\</span>yii<span class="token punctuation">\</span>grid<span class="token punctuation">\</span>GridView</span><span class="token operator">::</span><span class="token function">widget</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">'dataProvider'</span> <span class="token operator">=></span> <span class="token variable">$dataProvider</span><span class="token punctuation">,</span>
        <span class="token operator">...</span>
        <span class="token doc-comment comment">/*** Use the layout in the widget ***/</span>
        <span class="token string single-quoted-string">'layout'</span> <span class="token operator">=></span> <span class="token variable">$gridLayout</span><span class="token punctuation">,</span><span class="token operator">**</span><span class="token operator">*</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="gridview-actioncolumn-using-another-controller" tabindex="-1"><a class="header-anchor" href="#gridview-actioncolumn-using-another-controller" aria-hidden="true">#</a> GridView: ActionColumn - using another controller</h2>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code>                    <span class="token punctuation">[</span>
                        <span class="token string single-quoted-string">'class'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'yii\grid\ActionColumn'</span><span class="token punctuation">,</span>
                        <span class="token string single-quoted-string">'template'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'{view} {update}'</span><span class="token punctuation">,</span>
                        <span class="token string single-quoted-string">'controller'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'security-assessment'</span><span class="token punctuation">,</span>  <span class="token comment">// Use another controller</span>
                        <span class="token string single-quoted-string">'visibleButtons'</span> <span class="token operator">=></span> <span class="token punctuation">[</span>
                            <span class="token string single-quoted-string">'update'</span> <span class="token operator">=></span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">,</span> <span class="token variable">$key</span><span class="token punctuation">,</span> <span class="token variable">$index</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>   <span class="token comment">// Visible if the user is SEC-CTM and the associated SA is not closed yet</span>
                                <span class="token keyword">return</span> <span class="token variable">$model</span><span class="token operator">-></span><span class="token property">security_assessment_status_id</span> <span class="token operator">!=</span> <span class="token number">2</span> <span class="token operator">&amp;&amp;</span> <span class="token keyword">isset</span><span class="token punctuation">(</span><span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">user</span><span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> <span class="token keyword">isset</span><span class="token punctuation">(</span><span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">user</span><span class="token operator">-></span><span class="token property">identity</span><span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> <span class="token punctuation">(</span><span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">user</span><span class="token operator">-></span><span class="token property">identity</span><span class="token operator">-></span><span class="token function">is</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'security'</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                            <span class="token punctuation">}</span><span class="token punctuation">,</span>
                        <span class="token punctuation">]</span><span class="token punctuation">,</span>
                    <span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="working-checkboxcolumn" tabindex="-1"><a class="header-anchor" href="#working-checkboxcolumn" aria-hidden="true">#</a> Working CheckboxColumn</h2>
<p><strong>In the view</strong>:</p>
<p>The CheckboxColumn only usable with POST requests so you need a form. The form begins after Pjax</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code>    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span>
    <span class="token class-name static-context">Pjax</span><span class="token operator">::</span><span class="token function">begin</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'id'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'vulnerability-tickets-grid'</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name static-context">ActiveForm</span><span class="token operator">::</span><span class="token function">begin</span><span class="token punctuation">(</span>
            <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">'action'</span> <span class="token operator">=></span> <span class="token punctuation">[</span><span class="token string single-quoted-string">'vulnerability-ticket/commit-product-version'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'pvid'</span> <span class="token operator">=></span> <span class="token variable">$model</span><span class="token operator">-></span><span class="token property">product_version_id</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token punctuation">]</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>
</span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>In the GridView:</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code>    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-></span><span class="token property">hasDraftVulnerabilityTickets</span> <span class="token operator">&amp;&amp;</span> <span class="token variable">$user</span><span class="token operator">-></span><span class="token function">is</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'security'</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$gridColumns</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">'class'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'\yii\grid\CheckboxColumn'</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">'checkboxOptions'</span> <span class="token operator">=></span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">,</span> <span class="token variable">$key</span><span class="token punctuation">,</span> <span class="token variable">$index</span><span class="token punctuation">,</span> <span class="token variable">$column</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                  <span class="token comment">// do not display the checkbox when not usable</span>
                <span class="token variable">$disp</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-></span><span class="token property">vt_status</span> <span class="token operator">==</span> <span class="token string single-quoted-string">'vt/Draft'</span> <span class="token operator">||</span> <span class="token variable">$model</span><span class="token operator">-></span><span class="token property">to_be_deleted</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">?</span> <span class="token string single-quoted-string">'none;'</span> <span class="token punctuation">:</span> <span class="token string single-quoted-string">'block;'</span><span class="token punctuation">;</span>
                <span class="token comment">// setup checkbox options </span>
                <span class="token variable">$res</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">'style'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'display:'</span> <span class="token operator">.</span> <span class="token variable">$disp</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">'checked'</span> <span class="token operator">=></span> <span class="token constant boolean">true</span><span class="token punctuation">,</span>
                      <span class="token comment">// Disable when you do not want to POST with the form</span>
                    <span class="token string single-quoted-string">'disabled'</span> <span class="token operator">=></span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-></span><span class="token property">vt_status</span> <span class="token operator">==</span> <span class="token string single-quoted-string">'vt/Draft'</span> <span class="token operator">||</span> <span class="token variable">$model</span><span class="token operator">-></span><span class="token property">to_be_deleted</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">;</span>
                <span class="token keyword">return</span> <span class="token variable">$res</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span><span class="token punctuation">,</span>
            <span class="token comment">// Header cb is checked</span>
            <span class="token string single-quoted-string">'header'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'&lt;input type="checkbox" class="select-on-check-all" name="selection_all" value="1" checked>'</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>In the controller</strong>:</p>
<p>Store the selection in a session variable:</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code>    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">actionCommitProductVersion</span><span class="token punctuation">(</span><span class="token variable">$pvid</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">session</span><span class="token operator">-></span><span class="token function">has</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'selectedtickets'</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">session</span><span class="token operator">-></span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'selectedtickets'</span><span class="token punctuation">,</span> <span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">request</span><span class="token operator">-></span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'selection'</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Modify the query if has selections:</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code>        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">session</span><span class="token operator">-></span><span class="token function">has</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'selectedtickets'</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$st</span> <span class="token operator">=</span> <span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">session</span><span class="token operator">-></span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'selectedtickets'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$vtsDraft</span><span class="token operator">-></span><span class="token function">andWhere</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'IN'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'vulnerability_ticket_id'</span><span class="token punctuation">,</span> <span class="token variable">$st</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$vtsDel</span><span class="token operator">-></span><span class="token function">andWhere</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'IN'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'vulnerability_ticket_id'</span><span class="token punctuation">,</span> <span class="token variable">$st</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
