<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token doc-comment comment">/**
     * Save as PDF
     * <span class="token keyword">@param</span> <span class="token class-name"><span class="token keyword">integer</span></span> <span class="token parameter">$id</span>
     * <span class="token keyword">@param</span> <span class="token class-name"><span class="token keyword">string</span></span> <span class="token parameter">$format</span> The export format. Currently 'pdf' and 'xml' is accepted
     */</span>
    <span class="token keyword">function</span> <span class="token function-definition function">actionExport</span><span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">,</span> <span class="token variable">$format</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$model</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token function">findModel</span><span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">switch</span> <span class="token punctuation">(</span><span class="token variable">$format</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">case</span> <span class="token string double-quoted-string">"pdf"</span> <span class="token punctuation">:</span> <span class="token punctuation">{</span>
                    <span class="token variable">$p</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\</span>TCPDF</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'P'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'mm'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'A4'</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'UTF-8'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token variable">$this</span><span class="token operator">-></span><span class="token function">setPDFParams</span><span class="token punctuation">(</span><span class="token variable">$p</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'Security advisory'</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token operator">-></span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token variable">$p</span><span class="token operator">-></span><span class="token function">AddPage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token variable">$p</span><span class="token operator">-></span><span class="token function">setTextShadow</span><span class="token punctuation">(</span><span class="token keyword">array</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'enabled'</span> <span class="token operator">=></span> <span class="token constant boolean">true</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'depth_w'</span> <span class="token operator">=></span> <span class="token number">0.2</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'depth_h'</span> <span class="token operator">=></span> <span class="token number">0.2</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'color'</span> <span class="token operator">=></span> <span class="token keyword">array</span><span class="token punctuation">(</span><span class="token number">196</span><span class="token punctuation">,</span> <span class="token number">196</span><span class="token punctuation">,</span> <span class="token number">196</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'opacity'</span> <span class="token operator">=></span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'blend_mode'</span> <span class="token operator">=></span> <span class="token string single-quoted-string">'Normal'</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token function">render</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'view'</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">'model'</span> <span class="token operator">=></span> <span class="token variable">$model</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token variable">$p</span><span class="token operator">-></span><span class="token function">writeHTMLCell</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">''</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">''</span><span class="token punctuation">,</span> <span class="token variable">$content</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">''</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token variable">$p</span><span class="token operator">-></span><span class="token function">Output</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'security_advisory.pdf'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'I'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token keyword">break</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
            <span class="token keyword">default</span> <span class="token punctuation">:</span> <span class="token punctuation">{</span>
                    <span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">session</span><span class="token operator">-></span><span class="token function">setFlash</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'danger'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'Invalid document format requested! Use "pdf" or "xml" as a format string!'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token function">redirect</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'view'</span><span class="token punctuation">,</span>
                                <span class="token string single-quoted-string">'id'</span> <span class="token operator">=></span> <span class="token variable">$id</span><span class="token punctuation">,</span>
                    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                    <span class="token keyword">break</span><span class="token punctuation">;</span>
                <span class="token punctuation">}</span>
        <span class="token punctuation">}</span>
        <span class="token class-name static-context">Yii</span><span class="token operator">::</span><span class="token variable">$app</span><span class="token operator">-></span><span class="token property">session</span><span class="token operator">-></span><span class="token function">setFlash</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'warning'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'Not fully implemented yet'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token function">redirect</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'view'</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">'id'</span> <span class="token operator">=></span> <span class="token variable">$id</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">function</span> <span class="token function-definition function">setPDFParams</span><span class="token punctuation">(</span><span class="token variable">$pdf</span><span class="token punctuation">,</span> <span class="token variable">$title</span> <span class="token operator">=</span> <span class="token string single-quoted-string">''</span><span class="token punctuation">,</span> <span class="token variable">$subject</span> <span class="token operator">=</span> <span class="token string single-quoted-string">''</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetCreator</span><span class="token punctuation">(</span><span class="token constant">PDF_CREATOR</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetAuthor</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'HiSAT v2'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetTitle</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'Security advisory'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetSubject</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'for '</span> <span class="token operator">.</span> <span class="token variable">$subject</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetKeywords</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'advisory, PDF, hisat'</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetHeaderData</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'/../../../../../web/img/unify_header.png'</span><span class="token punctuation">,</span> <span class="token number">60</span><span class="token punctuation">,</span> <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">GetHeaderData</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'title'</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$title</span> <span class="token operator">.</span> <span class="token string single-quoted-string">' for '</span> <span class="token operator">.</span> <span class="token variable">$subject</span><span class="token punctuation">,</span> <span class="token keyword">array</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">64</span><span class="token punctuation">,</span> <span class="token number">255</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token keyword">array</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">64</span><span class="token punctuation">,</span> <span class="token number">128</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">setFooterData</span><span class="token punctuation">(</span><span class="token keyword">array</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">64</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token keyword">array</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">64</span><span class="token punctuation">,</span> <span class="token number">128</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">setHeaderFont</span><span class="token punctuation">(</span><span class="token keyword">Array</span><span class="token punctuation">(</span><span class="token constant">PDF_FONT_NAME_MAIN</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">''</span><span class="token punctuation">,</span> <span class="token constant">PDF_FONT_SIZE_MAIN</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">setFooterFont</span><span class="token punctuation">(</span><span class="token keyword">Array</span><span class="token punctuation">(</span><span class="token constant">PDF_FONT_NAME_DATA</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">''</span><span class="token punctuation">,</span> <span class="token constant">PDF_FONT_SIZE_DATA</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetDefaultMonospacedFont</span><span class="token punctuation">(</span><span class="token constant">PDF_FONT_MONOSPACED</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetMargins</span><span class="token punctuation">(</span><span class="token constant">PDF_MARGIN_LEFT</span><span class="token punctuation">,</span> <span class="token constant">PDF_MARGIN_TOP</span><span class="token punctuation">,</span> <span class="token constant">PDF_MARGIN_RIGHT</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetHeaderMargin</span><span class="token punctuation">(</span><span class="token constant">PDF_MARGIN_HEADER</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetFooterMargin</span><span class="token punctuation">(</span><span class="token constant">PDF_MARGIN_FOOTER</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetAutoPageBreak</span><span class="token punctuation">(</span><span class="token constant boolean">TRUE</span><span class="token punctuation">,</span> <span class="token constant">PDF_MARGIN_BOTTOM</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">setImageScale</span><span class="token punctuation">(</span><span class="token constant">PDF_IMAGE_SCALE_RATIO</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">setFontSubsetting</span><span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$pdf</span><span class="token operator">-></span><span class="token function">SetFont</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'dejavusans'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">''</span><span class="token punctuation">,</span> <span class="token number">14</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">''</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="activequery-overwrite-the-like-smth-behavior-of-the-yii-framework" tabindex="-1"><a class="header-anchor" href="#activequery-overwrite-the-like-smth-behavior-of-the-yii-framework" aria-hidden="true">#</a> ActiveQuery: overwrite the LIKE %smth% behavior of the Yii framework</h2>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token variable">$query</span><span class="token operator">-></span><span class="token function">andWhere</span><span class="token punctuation">(</span><span class="token string double-quoted-string">"CONCAT(product_line.major,'.',product_line.minor,'.',product_version.fix,'.',product_version.hotfix) like "</span> <span class="token operator">.</span> <span class="token string double-quoted-string">"'"</span> <span class="token operator">.</span> <span class="token variable">$this</span><span class="token operator">-></span><span class="token property">Version</span> <span class="token operator">.</span> <span class="token string double-quoted-string">"%'"</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="from-a-select-to-an-activerecord" tabindex="-1"><a class="header-anchor" href="#from-a-select-to-an-activerecord" aria-hidden="true">#</a> From a SELECT to an ActiveRecord</h2>
<p>This is the SELECT on the database what you are able to convert to an ActiveRecord query</p>
<div class="language-sql ext-sql line-numbers-mode"><pre v-pre class="language-sql"><code><span class="token keyword">SELECT</span> 
    <span class="token identifier"><span class="token punctuation">`</span>product_component<span class="token punctuation">`</span></span><span class="token punctuation">.</span><span class="token operator">*</span>
<span class="token keyword">FROM</span>
    <span class="token identifier"><span class="token punctuation">`</span>product_component<span class="token punctuation">`</span></span>
        <span class="token keyword">LEFT</span> <span class="token keyword">JOIN</span>
    <span class="token identifier"><span class="token punctuation">`</span>product_version<span class="token punctuation">`</span></span> <span class="token keyword">ON</span> <span class="token identifier"><span class="token punctuation">`</span>product_component<span class="token punctuation">`</span></span><span class="token punctuation">.</span><span class="token identifier"><span class="token punctuation">`</span>product_version_id<span class="token punctuation">`</span></span> <span class="token operator">=</span> <span class="token identifier"><span class="token punctuation">`</span>product_version<span class="token punctuation">`</span></span><span class="token punctuation">.</span><span class="token identifier"><span class="token punctuation">`</span>product_version_id<span class="token punctuation">`</span></span>
        <span class="token keyword">LEFT</span> <span class="token keyword">JOIN</span>
    <span class="token identifier"><span class="token punctuation">`</span>component_version<span class="token punctuation">`</span></span> <span class="token keyword">ON</span> <span class="token identifier"><span class="token punctuation">`</span>product_component<span class="token punctuation">`</span></span><span class="token punctuation">.</span><span class="token identifier"><span class="token punctuation">`</span>component_version_id<span class="token punctuation">`</span></span> <span class="token operator">=</span> <span class="token identifier"><span class="token punctuation">`</span>component_version<span class="token punctuation">`</span></span><span class="token punctuation">.</span><span class="token identifier"><span class="token punctuation">`</span>component_version_id<span class="token punctuation">`</span></span>
<span class="token keyword">WHERE</span>
    <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">`</span>psi_status<span class="token punctuation">`</span></span> <span class="token operator">IN</span> <span class="token punctuation">(</span><span class="token string">'psi/Open'</span> <span class="token punctuation">,</span> <span class="token string">'psi/Complete'</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
        <span class="token operator">AND</span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">`</span>component_version<span class="token punctuation">`</span></span><span class="token punctuation">.</span><span class="token identifier"><span class="token punctuation">`</span>component_line_id<span class="token punctuation">`</span></span> <span class="token operator">=</span> $ID<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>in this way:</p>
<div class="language-php ext-php line-numbers-mode"><pre v-pre class="language-php"><code><span class="token comment">// Search for all product_components</span>
            <span class="token variable">$pcs</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\</span>app<span class="token punctuation">\</span>models<span class="token punctuation">\</span>ProductComponent</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                    <span class="token operator">-></span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'LEFT JOIN'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'product_version'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'product_component.product_version_id = product_version.product_version_id'</span><span class="token punctuation">)</span>
                    <span class="token operator">-></span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string single-quoted-string">'LEFT JOIN'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'component_version'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'product_component.component_version_id = component_version.component_version_id'</span><span class="token punctuation">)</span>
                    <span class="token operator">-></span><span class="token function">where</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'psi_status'</span> <span class="token operator">=></span> <span class="token punctuation">[</span><span class="token string single-quoted-string">'psi/Open'</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">'psi/Complete'</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
                    <span class="token operator">-></span><span class="token function">andWhere</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">'component_version.component_line_id'</span> <span class="token operator">=></span> <span class="token variable">$id</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
                    <span class="token operator">-></span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div></template>


